<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\PlatformIdentity\Application\Usecase\Update;

use RuntimeException;
use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\PlatformIdentity;
use Civi\Lughauth\Shared\Exception\ConstraintException;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFail;

class PlatformIdentityUpdateCheck
{
    public function __construct(public readonly PlatformIdentityUpdateParams $input, public readonly PlatformIdentity $current)
    {
    }
    public function reject(RuntimeException|ConstraintFail $fail)
    {
        if ($fail instanceof ConstraintFail) {
            throw ConstraintException::ofFail($fail);
        } else {
            throw $fail;
        }
    }
}
